import numpy as np


def step_detector(data, window_size=15, threshold=8.0, drift=0.02):
    # 滑动中值滤波减少噪声
    def median_filter(x, k):
        k = int(k)
        y = np.zeros((len(x),))
        for i in range(len(x)):
            y[i] = np.median(x[max(i - k, 0):min(i + k + 1, len(x))])
        return y

    # 应用中值滤波
    filtered_data = median_filter(data, window_size // 2)

    # CUSUM检测
    def cusum(x, threshold, drift):
        pos = neg = 0
        alerts = []
        for i in range(1, len(x)):
            pos = max(0, pos + x[i] - x[i - 1] - drift)
            neg = max(0, neg - x[i] + x[i - 1] - drift)
            if pos > threshold or neg > threshold:
                alerts.append(i)
                pos = neg = 0
        return alerts

    # 返回检测到的阶跃点
    return cusum(filtered_data, threshold, drift)


